def hull(points):
 p=sorted(set(points))
 def cross(o,a,b): return (a[0]-o[0])*(b[1]-o[1])-(a[1]-o[1])*(b[0]-o[0])
 lo=[]
 for q in p:
  while len(lo)>=2 and cross(lo[-2],lo[-1],q)<=0: lo.pop()
  lo.append(q)
 up=[]
 for q in reversed(p):
  while len(up)>=2 and cross(up[-2],up[-1],q)<=0: up.pop()
  up.append(q)
 return lo[:-1]+up[:-1]
